arguments.command:
python3 - <<'EOF'
import json, sys
sys.path.insert(0, '/app/src')
import dag_code as dc

spec = json.load(open('/app/src/dag_spec.json'))
inputs = json.load(open('/app/src/inputs.json'))

fns = {n['id']: getattr(dc, n['name']) for n in spec['nodes'].values()}
values = dict(inputs)
trace = []
visited = set()

def resolve(nid):
    if nid in values:
        return values[nid]
    node = spec['nodes'][nid]
    vals = []
    for i in node['inputs']:
        vals.append(resolve(i))
    if nid not in visited:
        visited.add(nid)
        trace.append((nid, node['inputs'], vals))
    v = fns[nid](*vals)
    values[nid] = v
    return v

target = spec['target_node_id']
tv = resolve(target)

result = {
    "target": target,
    "value": tv,
    "dependency_trace": [
        {"node": nid, "inputs": [{"id": i, "value": v} for i, v in zip(ins, vals)], "value": values[nid]}
        for nid, ins, vals in trace
    ],
}
assert set(result) == {"target", "value", "dependency_trace"}
for e in result["dependency_trace"]:
    assert set(e) == {"node", "inputs", "value"}
    for ie in e["inputs"]:
        assert set(ie) == {"id", "value"}
import os
os.makedirs('/app/output', exist_ok=True)
with open('/app/output/result.json', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\n')
print(json.dumps(result, indent=2))
EOF
